INSERT INTO setting (id, type, value, note) VALUES ('economy.currency.max-balance', 'int', '10000000000', 'No balance (purse or bank) can ever exceed this. Extra coins are refused, never destroyed.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.currency.ledger-size', 'int', '50', 'Purse changes remembered per player (used by /economy ledger and the audit chain check).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.currency.bank-history-size', 'int', '40', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.currency.ledger-file', 'bool', 'false', 'Also append every purse change to plugins/VampyuyuSurvival/economy/ledger/<day>.log (needs a restart).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pay.enabled', 'bool', 'true', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pay.min', 'int', '1', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pay.max', 'int', '1000000', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pay.confirm-over', 'int', '500', 'Payments above this need "/pay confirm" within 30 seconds.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pay.cooldown-seconds', 'int', '5', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pay.daily-limit', 'int', '2500000', 'Total a player may send per UTC day (anti alt-funnelling).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pay.tax-percent', 'int', '0', 'Percent of each payment that disappears (0 disables).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.death.cause', 'text', 'pvp', 'pvp = only when killed by another player, any = every death, never = off.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.death.percent', 'int', '50', 'Share of the purse lost (the bank is never touched).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.death.max', 'int', '10000', 'The most that can be lost in one death.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.death.min-balance', 'int', '100', 'Purses below this lose nothing.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.death.drop-to-killer', 'bool', 'false', 'false = the coins are destroyed (an alt cannot farm a killer reward). true = the killer receives them.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.baltop.cache-seconds', 'int', '300', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.baltop.size', 'int', '100', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.safety.save-player-data', 'bool', 'true', 'Save the player''s data right after an item is escrowed into the bazaar or auction house, so a crash cannot bring the item back while the order still exists.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bank.interest-period-hours', 'int', '24', 'Real time between interest payments, in hours (interest is also paid for the time spent offline). 24 h x 0.5 % is about 0.5 % a day: do not shorten the period or raise the rates without watching "/economy audit".');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bank.max-catchup-periods', 'int', '3', 'Offline catch-up is limited to this many periods; the rest is forfeited.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.sell.protect-hotbar', 'bool', 'false', 'true = "Sell everything" and /sellall leave the 9 hotbar slots alone.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.buyback.size', 'int', '18', 'Items sold to a merchant stay buyable for what they paid: how many.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.buyback.seconds', 'int', '300', 'Items sold to a merchant stay buyable for what they paid: for how long.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pressure.enabled', 'bool', 'true', 'Server-wide sell pressure: every item sold to an NPC lowers that item''s sell price for everybody, and the effect fades. Stops endless farms.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pressure.soft-cap', 'int', '20000', 'multiplier = 1 / (1 + pressure / soft-cap), never below min-multiplier.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pressure.half-life-hours', 'int', '2', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.pressure.min-multiplier', 'real', '0.2', 'The sell price never falls below this share of its base.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bazaar.enabled', 'bool', 'true', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bazaar.tax-percent', 'real', '1.25', 'Percent of each sale kept by the market (taken from the seller on every fill, instant sells included).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bazaar.max-orders', 'int', '14', 'Open orders a player may have (buy and sell together).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bazaar.max-amount', 'int', '71680', 'The largest single order.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bazaar.max-price', 'int', '1000000', 'Highest price per item, in coins.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bazaar.price-band', 'real', '5.0', 'Orders must stay within this factor of the 24h average price (5 = from 1/5 to 5 times; 1 or less disables it). Stops manipulation with absurd prices.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bazaar.history-hours', 'int', '72', 'Hours of hourly price history kept per product (24..336).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.bazaar.persist-delay-ticks', 'int', '10', 'The market file is written this many ticks after a change; changes in the same window share one write.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.enabled', 'bool', 'true', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.max-listings', 'int', '7', 'Active listings per player.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.min-price', 'int', '10', 'Starting bid / Buy It Now lower bound, in coins.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.max-price', 'int', '10000000', 'Starting bid / Buy It Now upper bound, in coins.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.tax-percent', 'real', '1.0', 'Percent of the final price taken from the seller when an auction sells.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.bid-increment-percent', 'int', '5', 'A bid must beat the top bid by this percent, and by at least bid-increment-min coins.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.bid-increment-min', 'int', '1', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.anti-snipe-window-seconds', 'int', '120', 'A bid in the last window seconds restarts the clock to "extend" seconds (anti sniping), max-extensions times.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.anti-snipe-extend-seconds', 'int', '120', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.max-extensions', 'int', '10', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.durations-hours', 'list', '', 'Hours a listing may last (the menu cycles through these).');
INSERT INTO setting_item (setting_id, position, value) VALUES ('economy.auction.durations-hours', 0, '1');
INSERT INTO setting_item (setting_id, position, value) VALUES ('economy.auction.durations-hours', 1, '6');
INSERT INTO setting_item (setting_id, position, value) VALUES ('economy.auction.durations-hours', 2, '12');
INSERT INTO setting_item (setting_id, position, value) VALUES ('economy.auction.durations-hours', 3, '24');
INSERT INTO setting_item (setting_id, position, value) VALUES ('economy.auction.durations-hours', 4, '48');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.default-duration-hours', 'int', '12', 'Default listing duration.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.listing-fee.base-percent', 'real', '1.0', 'Listing fee, paid up front and never refunded: price * (base-percent + per-day-percent * hours / 24) %, between min and max coins.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.listing-fee.per-day-percent', 'real', '0.5', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.listing-fee.min', 'int', '25', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.listing-fee.max', 'int', '50000', '');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.history-size', 'int', '300', 'Finished sales kept for /ah history and the "recent price" line.');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.max-item-chars', 'int', '200000', 'Refuse an item whose serialised form is larger than this (stops giant shulker boxes bloating the file).');
INSERT INTO setting (id, type, value, note) VALUES ('economy.auction.persist-delay-ticks', 'int', '10', '');
